INSERT INTO `wp_comments` (`comment_ID`, `comment_post_ID`, `comment_author`, `comment_author_email`, `comment_author_url`, `comment_author_IP`, `comment_date`, `comment_date_gmt`, `comment_content`, `comment_karma`, `comment_approved`, `comment_agent`, `comment_type`, `comment_parent`, `user_id`) VALUES 
('1', '1', 'A WordPress Commenter', 'wapuu@wordpress.example', 'https://wordpress.org/', '', '2026-09-12 04:16:31', '2026-09-12 04:16:31', 'Hi, this is a comment.\nTo get started with moderating, editing, and deleting comments, please visit the Comments screen in the dashboard.\nCommenter avatars come from <a href=\"https://gravatar.com/\">Gravatar</a>.', '0', 'post-trashed', '', 'comment', '0', '0'),
('2', '22', 'Wanjiru', 'wanjiru906@gmail.com', '', '', '2026-03-17 11:50:38', '2026-03-17 11:50:38', 'This hair is so soft and blends perfectly with my natural hair. Highly recommend!', '0', '1', '', 'review', '0', '0'),
('3', '22', 'Akinyi', 'akinyi566@gmail.com', '', '', '2026-05-03 11:50:39', '2026-05-03 11:50:39', 'Exactly as described. Installation was quick and easy, even for a first-timer.', '0', '1', '', 'review', '0', '0'),
('4', '22', 'Chebet', 'chebet516@gmail.com', '', '', '2026-07-20 11:50:39', '2026-07-20 11:50:39', 'I\'ve bought crochet hair before but this is by far the best quality I\'ve gotten.', '0', '1', '', 'review', '0', '0'),
('5', '22', 'Wangari', 'wangari624@gmail.com', '', '', '2026-04-16 11:50:39', '2026-04-16 11:50:39', 'No shedding, no tangling. Very happy with this purchase.', '0', '1', '', 'review', '0', '0'),
('6', '22', 'Nyokabi', 'nyokabi337@gmail.com', '', '', '2026-08-25 11:50:39', '2026-08-25 11:50:39', 'The body wave pattern looks so natural. Got so many compliments!', '0', '1', '', 'review', '0', '0'),
('7', '22', 'Adhiambo', 'adhiambo645@gmail.com', '', '', '2026-05-09 11:50:39', '2026-05-09 11:50:39', 'Great value for the price. Will definitely order again.', '0', '1', '', 'review', '0', '0'),
('8', '22', 'Wairimu', 'wairimu666@gmail.com', '', '', '2026-04-18 11:50:39', '2026-04-18 11:50:39', 'Took me less than an hour to install. Super beginner friendly like it says.', '0', '1', '', 'review', '0', '0'),
('9', '22', 'Njeri', 'njeri279@gmail.com', '', '', '2026-05-17 11:50:40', '2026-05-17 11:50:40', 'The hair feels premium, not like the cheap synthetic stuff I\'ve tried before.', '0', '1', '', 'review', '0', '0'),
('10', '22', 'Achieng', 'achieng505@gmail.com', '', '', '2026-05-02 11:50:40', '2026-05-02 11:50:40', 'Delivery was fast and the hair arrived well packaged.', '0', '1', '', 'review', '0', '0'),
('11', '22', 'Muthoni', 'muthoni408@gmail.com', '', '', '2026-08-17 11:50:40', '2026-08-17 11:50:40', 'I was skeptical about ordering online but this exceeded my expectations.', '0', '1', '', 'review', '0', '0'),
('12', '22', 'Wambui', 'wambui280@gmail.com', '', '', '2026-07-05 11:50:40', '2026-07-05 11:50:40', 'Holds curls beautifully and doesn\'t feel heavy on my scalp.', '0', '1', '', 'review', '0', '0'),
('13', '22', 'Amina', 'amina525@gmail.com', '', '', '2026-03-15 11:50:40', '2026-03-15 11:50:40', 'This is my third time ordering. Consistent quality every time.', '0', '1', '', 'review', '0', '0'),
('14', '22', 'Fatuma', 'fatuma532@gmail.com', '', '', '2026-05-22 11:50:40', '2026-05-22 11:50:40', 'Perfect length and the color matched my hair exactly.', '0', '1', '', 'review', '0', '0'),
('15', '22', 'Zawadi', 'zawadi994@gmail.com', '', '', '2026-05-30 11:50:41', '2026-05-30 11:50:41', 'My stylist was impressed with how easy it was to work with.', '0', '1', '', 'review', '0', '0'),
('16', '22', 'Nyambura', 'nyambura575@gmail.com', '', '', '2026-06-10 11:50:41', '2026-06-10 11:50:41', 'Soft, bouncy, and lasted me over two months with proper care.', '0', '1', '', 'review', '0', '0'),
('17', '22', 'Waithera', 'waithera562@gmail.com', '', '', '2026-03-20 11:50:41', '2026-03-20 11:50:41', 'Best crochet hair I\'ve used. The strands didn\'t slip out at all.', '0', '1', '', 'review', '0', '0'),
('18', '22', 'Kerubo', 'kerubo281@gmail.com', '', '', '2026-05-31 11:50:41', '2026-05-31 11:50:41', 'Looks so real people keep asking if it\'s my own hair!', '0', '1', '', 'review', '0', '0'),
('19', '22', 'Moraa', 'moraa599@gmail.com', '', '', '2026-03-05 11:50:41', '2026-03-05 11:50:41', 'Affordable and does not compromise on quality at all.', '0', '1', '', 'review', '0', '0'),
('20', '22', 'Cherono', 'cherono461@gmail.com', '', '', '2026-08-28 11:50:41', '2026-08-28 11:50:41', 'Easy install, minimal shedding, and it still looks fresh after weeks.', '0', '1', '', 'review', '0', '0'),
('21', '22', 'Wanjiku', 'wanjiku504@gmail.com', '', '', '2026-05-07 11:50:42', '2026-05-07 11:50:42', 'I love how full and voluminous it looks after installing.', '0', '1', '', 'review', '0', '0'),
('22', '22', 'Atieno', 'atieno188@gmail.com', '', '', '2026-02-28 11:50:42', '2026-02-28 11:50:42', 'This saved me so much money compared to salon extensions.', '0', '1', '', 'review', '0', '0'),
('23', '22', 'Auma', 'auma353@gmail.com', '', '', '2026-09-06 11:50:42', '2026-09-06 11:50:42', 'The invisible string design really does make it look seamless.', '0', '1', '', 'review', '0', '0'),
